// Motor values for the Motors tab (Advanced motor settings): picking a brand and a model fills in KV, stator size and
// magnet count. Collected from the manufacturers' published tables and retailer copies of them (source per entry).
// Brands are welcome to add and correct their own motors.
//
// This is all the motor thermal estimator needs from the motor:
//   kv                  rpm per volt, as on the label
//   statorDiameterMm    stator diameter, mm (the first two digits of "2207")
//   statorHeightDmm     stator height, 0.1 mm (the last digits: 2207 -> 70, 2203.5 -> 35)
//   magnets             magnet count (the "P" of 12N14P), Betaflight's motor_poles; 0 = not published
// The winding resistance follows from KV and stator size (a law fitted on 772 datasheets); published resistances,
// idle currents and temperatures were used to validate the estimator and are not needed here:
// https://github.com/350d/betaflight/blob/assets/motor-thermal/motor-thermal/DATASHEET_VALIDATION.md

export interface MotorSpec {
    brand: string;
    model: string;
    kv: number;
    statorDiameterMm: number;
    statorHeightDmm: number;
    magnets: number;
    source: string;
}

